//go:build integration

package integration

import (
	"strings"
	"testing"
	"time"

	"github.com/thealexjo/binwave/internal/config"
	"github.com/thealexjo/binwave/test/testenv"
)

// destructiveStatements are run on a real server, so that the text the server writes to the
// binlog (backticks, a "generated by server" comment, the database qualifier) is what the DDL
// parser sees, not what a test author imagines it looks like.
var destructiveStatements = []struct {
	name, setup, statement string
}{
	{"drop table", "", "DROP TABLE binwave.victim"},
	{"drop table if exists", "", "DROP TABLE IF EXISTS binwave.victim"},
	{"truncate", "", "TRUNCATE TABLE binwave.victim"},
	{
		"drop partition",
		"CREATE TABLE binwave.victim (id INT NOT NULL, PRIMARY KEY (id)) PARTITION BY RANGE (id) (PARTITION p0 VALUES LESS THAN (100), PARTITION p1 VALUES LESS THAN (200))",
		"ALTER TABLE binwave.victim DROP PARTITION p0",
	},
	{
		"truncate partition",
		"CREATE TABLE binwave.victim (id INT NOT NULL, PRIMARY KEY (id)) PARTITION BY RANGE (id) (PARTITION p0 VALUES LESS THAN (100), PARTITION p1 VALUES LESS THAN (200))",
		"ALTER TABLE binwave.victim TRUNCATE PARTITION p0",
	},
}

// TestDropAndTruncateOfARealServerAreMirroredInFullMode: what the source does to its tables, the
// replica does: a dropped table is gone, a truncated one is empty, and replication goes on.
func TestDropAndTruncateOfARealServerAreMirroredInFullMode(t *testing.T) {
	t.Parallel()
	for _, tt := range destructiveStatements[:3] {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			my := testenv.StartMySQL(t)
			ch := testenv.StartClickHouse(t)
			mustExec(t, my, "CREATE TABLE binwave.victim (id INT PRIMARY KEY)", "CREATE TABLE binwave.other (id INT PRIMARY KEY)")
			cfg := engineConfig(t, my, ch, "file")
			cfg.DDL.Mode = config.DDLFull
			e := startHubEngine(t, cfg)
			mustExec(t, my, "INSERT INTO binwave.victim VALUES (1), (2)", "INSERT INTO binwave.other VALUES (1)")
			waitUntil(t, "the rows", 60*time.Second, func() bool { return chRowCount(t, ch, "victim") == 2 && chRowCount(t, ch, "other") == 1 })

			mustExec(t, my, tt.statement, "INSERT INTO binwave.other VALUES (2)")

			waitUntil(t, "the statement to be mirrored", 60*time.Second, func() bool {
				want := 0
				if strings.HasPrefix(tt.statement, "DROP") {
					want = -1 // the table does not exist any more
				}
				return chRowCount(t, ch, "victim") == want && chRowCount(t, ch, "other") == 2
			})
			e.stillRunning(t)
			if got := e.quarantinedTables(); len(got) != 0 {
				t.Errorf("quarantined %v", got)
			}
		})
	}
}

// TestDropAndTruncateAreNotAppliedInAdditiveMode: additive never removes anything, and says so.
func TestDropAndTruncateAreNotAppliedInAdditiveMode(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	mustExec(t, my, "CREATE TABLE binwave.acct (id INT PRIMARY KEY, owner VARCHAR(20) NOT NULL, qty INT NOT NULL)")
	cfg := engineConfig(t, my, ch, "file")
	cfg.DDL.Mode = config.DDLAdditive

	e := startEngine(t, cfg)
	mustExec(t, my, "INSERT INTO binwave.acct VALUES (1, 'a', 1), (2, 'b', 2)")
	waitForConvergence(t, my, ch)

	mustExec(t, my, "TRUNCATE TABLE binwave.acct", "INSERT INTO binwave.acct VALUES (3, 'c', 3)")

	// ClickHouse keeps the rows the source truncated, and replication goes on.
	waitUntil(t, "the row inserted after the TRUNCATE", 60*time.Second, func() bool {
		got, ok := clickhouseAccounts(t, ch)
		_, has3 := got[3]
		return ok && has3
	})
	got, _ := clickhouseAccounts(t, ch)
	if len(got) != 3 {
		t.Errorf("ClickHouse holds %v, want the two rows of before the TRUNCATE and the new one", got)
	}
	select {
	case err := <-e.done:
		t.Fatalf("the engine stopped: %v", err)
	default:
	}
	if err := e.stop(t); err != nil {
		t.Errorf("stop returned %v", err)
	}
}

// TestPartitionStatementsOfARealServerAreSkippedWithAWarning: the rows stay in ClickHouse, the
// statement is counted, and replication goes on (mirroring partition statements is not supported yet).
func TestPartitionStatementsOfARealServerAreSkippedWithAWarning(t *testing.T) {
	t.Parallel()
	for _, tt := range destructiveStatements[3:] {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			my := testenv.StartMySQL(t)
			ch := testenv.StartClickHouse(t)
			mustExec(t, my, tt.setup, "CREATE TABLE binwave.other (id INT PRIMARY KEY)")
			cfg := engineConfig(t, my, ch, "file")
			e := startHubEngine(t, cfg)
			mustExec(t, my, "INSERT INTO binwave.victim VALUES (1), (150)")
			waitUntil(t, "the rows", 60*time.Second, func() bool { return chRowCount(t, ch, "victim") == 2 })

			mustExec(t, my, tt.statement, "INSERT INTO binwave.other VALUES (1)")

			waitUntil(t, "replication to go on", 60*time.Second, func() bool { return chRowCount(t, ch, "other") == 1 })
			if chRowCount(t, ch, "victim") != 2 {
				t.Error("rows were removed although partition operations are not applied")
			}
			e.stillRunning(t)
		})
	}
}

// TestDropDatabaseOfARealServerDropsTheReplicatedTables: the tables of the dropped database that
// binwave wrote are dropped in ClickHouse, the others stay.
func TestDropDatabaseOfARealServerDropsTheReplicatedTables(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	for _, q := range []string{"CREATE DATABASE other", "GRANT ALL ON other.* TO 'binwave'@'%'"} {
		if _, err := rootDB(t, my).Exec(q); err != nil {
			t.Fatal(q, err)
		}
	}
	mustExec(t, my, "CREATE TABLE other.t (id INT PRIMARY KEY)", "CREATE TABLE binwave.keep (id INT PRIMARY KEY)")
	cfg := engineConfigWith(t, my, ch, "file", `tables: {include: ["binwave.*", "other.*"]}`)
	cfg.DDL.Mode = config.DDLFull
	e := startHubEngine(t, cfg)
	mustExec(t, my, "INSERT INTO other.t VALUES (1)", "INSERT INTO binwave.keep VALUES (1)")
	waitUntil(t, "the rows", 60*time.Second, func() bool { return chRowCount(t, ch, "t") == 1 && chRowCount(t, ch, "keep") == 1 })

	mustExec(t, my, "DROP DATABASE other", "INSERT INTO binwave.keep VALUES (2)")

	waitUntil(t, "the tables of the dropped database to go", 60*time.Second, func() bool {
		return chRowCount(t, ch, "t") == -1 && chRowCount(t, ch, "keep") == 2
	})
	e.stillRunning(t)
}
